import React from 'react';
import { Grid, TextField, Typography } from '@mui/material';
import {
  normalizeRenewablePpa,
  renewableProductionCost,
} from '../../shared/renewablePowerBalance';

export type RenewablePpaValue = {
  counterparty: string;
  reference: string;
  rateInrPerKwh: number;
  contractedKwhPerMonth: number;
  sourceDistanceKm: number;
  startDate: string;
  endDate: string;
};

type RenewablePpaFieldsProps = {
  value: RenewablePpaValue;
  generatedKwh: number;
  onChange: (ppa: RenewablePpaValue) => void;
  disabled?: boolean;
};

const formatInr = (amount: number) => amount.toLocaleString('en-IN', {
  minimumFractionDigits: 2,
  maximumFractionDigits: 2,
});

const RenewablePpaFields: React.FC<RenewablePpaFieldsProps> = ({
  value,
  generatedKwh,
  onChange,
  disabled = false,
}) => {
  const ppa = normalizeRenewablePpa(value);
  const cost = renewableProductionCost(generatedKwh, ppa);
  const update = (patch: Partial<RenewablePpaValue>) => {
    onChange(normalizeRenewablePpa({ ...ppa, ...patch }));
  };

  return (
    <Grid container spacing={2} sx={{ mb: 1.5 }} data-testid="renewable-ppa-fields">
      <Grid item xs={12}>
        <Typography variant="subtitle2" sx={{ fontWeight: 700 }}>
          Renewable power purchase agreement
        </Typography>
        <Typography variant="body2" color="text.secondary">
          The PPA rate is the cost of this renewable power. There is no separate production-cost price.
        </Typography>
      </Grid>
      <Grid item xs={12} md={4}>
        <TextField
          fullWidth
          size="small"
          label="PPA seller"
          value={ppa.counterparty}
          disabled={disabled}
          onChange={(event) => update({ counterparty: event.target.value })}
          inputProps={{ maxLength: 200 }}
        />
      </Grid>
      <Grid item xs={12} md={4}>
        <TextField
          fullWidth
          size="small"
          label="PPA reference"
          value={ppa.reference}
          disabled={disabled}
          onChange={(event) => update({ reference: event.target.value })}
          inputProps={{ maxLength: 120 }}
        />
      </Grid>
      <Grid item xs={12} md={4}>
        <TextField
          fullWidth
          size="small"
          type="number"
          label="PPA rate (INR/kWh)"
          value={ppa.rateInrPerKwh}
          disabled={disabled}
          onChange={(event) => update({ rateInrPerKwh: Number(event.target.value) })}
          helperText="This rate is the production cost."
          inputProps={{ min: 0, step: 0.01, 'data-testid': 'renewable-ppa-rate' }}
        />
      </Grid>
      <Grid item xs={12} md={4}>
        <TextField
          fullWidth
          size="small"
          type="number"
          label="Contracted energy (kWh/month)"
          value={ppa.contractedKwhPerMonth}
          disabled={disabled}
          onChange={(event) => update({ contractedKwhPerMonth: Number(event.target.value) })}
          helperText="Leave 0 to price all generation at the PPA rate."
          inputProps={{ min: 0, step: 1 }}
        />
      </Grid>
      <Grid item xs={12} md={4}>
        <TextField
          fullWidth
          size="small"
          type="date"
          label="PPA start"
          value={ppa.startDate}
          disabled={disabled}
          onChange={(event) => update({ startDate: event.target.value })}
          InputLabelProps={{ shrink: true }}
        />
      </Grid>
      <Grid item xs={12} md={4}>
        <TextField
          fullWidth
          size="small"
          type="number"
          label="Distance from source to site (km)"
          value={ppa.sourceDistanceKm}
          disabled={disabled}
          onChange={(event) => update({ sourceDistanceKm: Number(event.target.value) })}
          helperText="Enter this when the PPA plant is away from the site. Green-tariff electricity then includes transmission and distribution loss."
          inputProps={{ min: 0, step: 0.1, 'data-testid': 'renewable-source-distance' }}
        />
      </Grid>
      <Grid item xs={12} md={4}>
        <TextField
          fullWidth
          size="small"
          type="date"
          label="PPA end"
          value={ppa.endDate}
          disabled={disabled}
          onChange={(event) => update({ endDate: event.target.value })}
          InputLabelProps={{ shrink: true }}
        />
      </Grid>
      <Grid item xs={12}>
        <Typography variant="body2" data-testid="renewable-production-cost">
          {cost.rateInrPerKwh > 0
            ? `Production cost follows the PPA: ${cost.billedKwh.toLocaleString('en-IN')} kWh × ₹${formatInr(cost.rateInrPerKwh)} = ₹${formatInr(cost.productionCostInr)}.`
            : 'Enter the PPA rate. That rate is the cost of this renewable power.'}
        </Typography>
      </Grid>
    </Grid>
  );
};

export default RenewablePpaFields;
