import React from 'react';
import { Alert } from '@mui/material';

export type RenewablePowerBalanceNoticeProps = {
  generationKwh: number;
  selfUseKwh: number;
  gridImportKwh: number;
  gridExportKwh: number;
  renewableBalance: string;
  annualGenerationKwh?: number;
  installedCapacityKw?: number;
  generationLocationLabel?: string;
  sourceDistanceKm?: number;
};

export const renewablePowerBalanceText = ({
  selfUseKwh,
  gridImportKwh,
  gridExportKwh,
  renewableBalance,
  annualGenerationKwh = 0,
  generationLocationLabel = '',
  sourceDistanceKm = 0,
}: RenewablePowerBalanceNoticeProps): string => {
  const balance = renewableBalance === 'grid_export'
    ? `Renewable generation is higher than power used. ${selfUseKwh.toLocaleString()} kWh/month is used on site. ${gridExportKwh.toLocaleString()} kWh/month is exported to the grid.`
    : selfUseKwh > 0 && gridImportKwh > 0
      ? `Power used is higher than renewable generation. All ${selfUseKwh.toLocaleString()} kWh/month of renewable generation is used on site. ${gridImportKwh.toLocaleString()} kWh/month is taken from the grid.`
      : selfUseKwh > 0
        ? `Renewable generation covers power used. ${selfUseKwh.toLocaleString()} kWh/month is used on site and none is exported.`
        : `Estimated net grid electricity: ${gridImportKwh.toLocaleString()} kWh/month.`;
  const annual = annualGenerationKwh > 0
    ? ` ${annualGenerationKwh.toLocaleString()} kWh/year generation is stored for compliance reports.`
    : '';
  const location = generationLocationLabel
    ? ` Renewable plant: ${generationLocationLabel}.`
    : '';
  const distance = Number(sourceDistanceKm) > 0
    ? ` The renewable source is ${sourceDistanceKm} km from the site.`
    : '';
  return `${balance}${annual}${location}${distance}`;
};

const RenewablePowerBalanceNotice: React.FC<RenewablePowerBalanceNoticeProps> = (props) => {
  if (props.generationKwh <= 0 && (props.installedCapacityKw || 0) <= 0) {
    return null;
  }
  return (
    <Alert severity="info" sx={{ mb: 1.5 }} data-testid="renewable-power-balance">
      {renewablePowerBalanceText(props)}
    </Alert>
  );
};

export default RenewablePowerBalanceNotice;
