/**
 * Live UI previews for metered activity. Scope 2 uses the CEA weighted average.
 * Transmission and distribution is 17.63% of that Scope 2 figure and is added
 * in the transaction inventory, not inside the Scope 2 factor.
 */
export const CEA_GRID_KG_PER_KWH = 0.71;
export const MSME_GRID_PROXY_KG_PER_KWH = 0.8;
export const CEA_TD_LOSS_RATE = 0.1763;
export const DIESEL_COMBUSTION_KG_PER_LITRE = 2.68;

export const gridKgPerKwhForPolicy = (policy?: string | null): number =>
  policy === 'msme_proxy_0_80' ? MSME_GRID_PROXY_KG_PER_KWH : CEA_GRID_KG_PER_KWH;

export const scope2KgFromKwh = (kwh: number, policy?: string | null): number => {
  const quantity = Number.isFinite(kwh) ? Math.max(0, kwh) : 0;
  return Number((quantity * gridKgPerKwhForPolicy(policy)).toFixed(2));
};

export const gridPreviewCaption = (policy?: string | null): string => {
  const factor = gridKgPerKwhForPolicy(policy);
  if (policy === 'msme_proxy_0_80') {
    return `${factor.toFixed(2)} kg CO₂e/kWh MSME conservative proxy. Scope 2 only.`;
  }
  return `${factor.toFixed(2)} kg CO₂e/kWh CEA. Scope 2 only. Transaction inventory adds T&D at 17.63% of this Scope 2 figure.`;
};
